def countExactlyKDistinct(nums, k):
    def at_most(m):
        if m == 0:
            return 0
        freq = {}
        left = 0
        total = 0
        for right, x in enumerate(nums):
            freq[x] = freq.get(x, 0) + 1
            while len(freq) > m:
                y = nums[left]
                freq[y] -= 1
                if freq[y] == 0:
                    del freq[y]
                left += 1
            total += right - left + 1
        return total
    return at_most(k) - at_most(k - 1)
